cat > /tmp/install_seq.R <<'EOF'
options(timeout = 900)
options(repos = c(CRAN = "https://cloud.r-project.org"))
ap <- available.packages(repos = "https://cloud.r-project.org")
hard <- c("Depends","Imports","LinkingTo")
closure <- unique(unlist(tools::package_dependencies("rstan", db=ap, which=hard, recursive=TRUE)))
closure <- c("rstan", closure)
installed <- rownames(installed.packages())
remaining <- setdiff(closure, installed)
cat("Remaining:", length(remaining), "\n")

ddeps <- function(p){ if(p %in% rownames(ap)) unlist(tools::package_dependencies(p, db=ap, which=hard, recursive=FALSE)) else character(0) }

attempts <- setNames(rep(0L, remaining), remaining)
progress <- TRUE
while (length(remaining)>0 && progress) {
  progress <- FALSE
  for (p in remaining) {
    dd <- ddeps(p)
    if (length(intersect(dd, remaining))==0) {
      cat("\n>>> install:", p, "(attempt", attempts[p]+1, ")\n", sep="")
      res <- tryCatch({ install.packages(p, dependencies=FALSE, type="source"); TRUE }, error=function(e){cat("ERR:",conditionMessage(e),"\n");FALSE})
      installed <- rownames(installed.packages())
      if (p %in% installed) {
        cat(">>> OK", p, "\n"); remaining <- setdiff(remaining, p); attempts[p] <- 0L
      } else {
        attempts[p] <- attempts[p] + 1L
        cat(">>> FAILED", p, "\n")
        if (attempts[p] >= 2) { cat("ABORT: cannot build", p, "\n"); progress <- NA } else { progress <- TRUE }
      }
      break
    }
  }
}
cat("\n===== DONE, remaining:", length(remaining), "=====\n")
if (!length(remaining)) { library(rstan); cat("rstan version:", as.character(packageVersion("rstan")), "\n"); cat("SUCCESS_MARKER\n") }
EOF
echo 'sequential script written'

